"use client";

import { useEffect, useState } from "react";

const DASHBOARD_URL = "http://localhost:8000/api/dashboard/pge";

type RinEntry = {
  rin: string;
  rate_name: string | null;
  last_success: string | null;
};

type Dashboard = {
  provider: string;
  last_checked: string | null;
  total_rins: number;
  success_count: number;
  failed_count: number;
  failed_rins: RinEntry[];
  successful_rins: RinEntry[];
};

type LoadState =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "ready"; data: Dashboard };

/**
 * The API is the source of truth, but normalising the payload here keeps the
 * render tree safe: a slow/partial response can never make `.map()` explode.
 */
function normalizeDashboard(payload: unknown): Dashboard {
  const raw = (payload ?? {}) as Partial<Dashboard>;
  return {
    provider: typeof raw.provider === "string" ? raw.provider : "pge",
    last_checked: raw.last_checked ?? null,
    total_rins: typeof raw.total_rins === "number" ? raw.total_rins : 0,
    success_count: typeof raw.success_count === "number" ? raw.success_count : 0,
    failed_count: typeof raw.failed_count === "number" ? raw.failed_count : 0,
    failed_rins: Array.isArray(raw.failed_rins) ? raw.failed_rins : [],
    successful_rins: Array.isArray(raw.successful_rins) ? raw.successful_rins : [],
  };
}

export default function Page() {
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [reloadToken, setReloadToken] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: "loading" });

    async function loadDashboard() {
      try {
        const response = await fetch(DASHBOARD_URL, {
          signal: controller.signal,
          cache: "no-store",
          headers: { Accept: "application/json" },
        });

        if (!response.ok) {
          let detail = `Request failed (HTTP ${response.status}).`;
          try {
            const body = (await response.json()) as { detail?: unknown };
            if (typeof body.detail === "string") {
              detail = body.detail;
            }
          } catch {
            // Body was empty or not JSON; keep the generic status message.
          }
          throw new Error(detail);
        }

        const payload = await response.json();
        setState({ status: "ready", data: normalizeDashboard(payload) });
      } catch (error) {
        if (controller.signal.aborted) {
          return;
        }
        setState({
          status: "error",
          message:
            error instanceof Error ? error.message : "Could not load RIN data.",
        });
      }
    }

    void loadDashboard();
    return () => controller.abort();
  }, [reloadToken]);

  const reload = () => setReloadToken((token) => token + 1);

  return (
    <main className="page" aria-busy={state.status === "loading"}>
      <header className="page-header">
        <p className="eyebrow">PG&amp;E · RIN monitoring</p>
        <h1>RIN Watch</h1>
        <p className="subtitle">
          Realtime MIDAS publishing status for every PG&amp;E rate plan.
        </p>
      </header>

      {state.status === "loading" ? <DashboardSkeleton /> : null}

      {state.status === "error" ? (
        <section className="panel error-panel" role="alert">
          <h2>Could not load RIN data</h2>
          <p>{state.message}</p>
          <p className="hint">
            Make sure the API is running:{" "}
            <code>uvicorn main:app --reload --port 8000</code>
          </p>
          <button type="button" className="button" onClick={reload}>
            Try again
          </button>
        </section>
      ) : null}

      {state.status === "ready" ? (
        <DashboardView data={state.data} onRefresh={reload} />
      ) : null}
    </main>
  );
}

function DashboardView({
  data,
  onRefresh,
}: {
  data: Dashboard;
  onRefresh: () => void;
}) {
  return (
    <div className="stack">
      <section className="panel">
        <div className="panel-heading">
          <div>
            <h2>{data.provider.toUpperCase()} overview</h2>
            <p className="hint">
              Last checked: {data.last_checked ?? "not checked yet"}
            </p>
          </div>
          <button type="button" className="button" onClick={onRefresh}>
            Refresh
          </button>
        </div>

        <dl className="stat-grid">
          <Stat label="Tracked RINs" value={data.total_rins} />
          <Stat label="Published today" value={data.success_count} tone="ok" />
          <Stat label="Missing today" value={data.failed_count} tone="alert" />
        </dl>
      </section>

      <RinList
        title="Needs attention"
        description="RINs without a value published today, stalest first."
        entries={data.failed_rins}
        emptyMessage="Every tracked RIN published a value today."
        tone="alert"
      />

      <RinList
        title="Published today"
        description="RINs that returned at least one value from MIDAS today."
        entries={data.successful_rins}
        emptyMessage="No RIN has published a value today yet."
        tone="ok"
      />
    </div>
  );
}

function Stat({
  label,
  value,
  tone,
}: {
  label: string;
  value: number;
  tone?: "ok" | "alert";
}) {
  const toneClass = tone ? ` stat-value--${tone}` : "";
  return (
    <div className="stat">
      <dt>{label}</dt>
      <dd className={`stat-value${toneClass}`}>{value}</dd>
    </div>
  );
}

function RinList({
  title,
  description,
  entries,
  emptyMessage,
  tone,
}: {
  title: string;
  description: string;
  entries: RinEntry[];
  emptyMessage: string;
  tone: "ok" | "alert";
}) {
  return (
    <section className="panel">
      <div className="panel-heading">
        <div>
          <h2>{title}</h2>
          <p className="hint">{description}</p>
        </div>
        <span className={`badge badge--${tone}`}>{entries.length}</span>
      </div>

      {entries.length === 0 ? (
        <p className="empty">{emptyMessage}</p>
      ) : (
        <ul className="rin-list">
          {entries.map((entry) => (
            <li key={entry.rin} className="rin-row">
              <div className="rin-main">
                <span className="rin-code">{entry.rin}</span>
                <span className="rin-rate">{entry.rate_name ?? "—"}</span>
              </div>
              <span className="rin-meta">
                {entry.last_success
                  ? `Last value: ${entry.last_success}`
                  : "Never published"}
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function DashboardSkeleton() {
  return (
    <div className="stack" role="status" aria-live="polite">
      <span className="sr-only">Loading RIN status…</span>

      <section className="panel">
        <div className="panel-heading">
          <div className="skeleton-line-group">
            <div className="skeleton skeleton-line skeleton-line--title" />
            <div className="skeleton skeleton-line skeleton-line--short" />
          </div>
        </div>
        <div className="stat-grid">
          {[0, 1, 2].map((index) => (
            <div className="stat" key={index}>
              <div className="skeleton skeleton-line skeleton-line--label" />
              <div className="skeleton skeleton-line skeleton-line--value" />
            </div>
          ))}
        </div>
      </section>

      {[0, 1].map((group) => (
        <section className="panel" key={group}>
          <div className="skeleton-line-group">
            <div className="skeleton skeleton-line skeleton-line--title" />
            <div className="skeleton skeleton-line skeleton-line--short" />
          </div>
          <ul className="rin-list">
            {[0, 1, 2].map((row) => (
              <li className="rin-row" key={row}>
                <div className="rin-main">
                  <div className="skeleton skeleton-line skeleton-line--code" />
                  <div className="skeleton skeleton-line skeleton-line--rate" />
                </div>
                <div className="skeleton skeleton-line skeleton-line--meta" />
              </li>
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}

